static const char*scene_names[]={"Sala de imprensa","Vestiário","Cena removida","Jogador individual","Técnico individual","Foto da equipe","Academia","CT de treinamento"};
static const wchar_t*scene_files[]={L"sala-imprensa.xml",L"vestiario.xml",L"cena-removida.xml",L"jogador.xml",L"tecnico.xml",L"foto-equipe.xml",L"academia.xml",L"ct-treinamento.xml"};
static bool valid_scene(int s){return s>=0&&s<8&&s!=2;}
static fs::path project_directory(const fs::path& executable_directory){
    auto link=executable_directory/L"new-experience.ini";
    if(!fs::exists(link))return executable_directory;
    wchar_t configured[32768]={};
    GetPrivateProfileStringW(L"vinculo",L"projeto",L"",configured,32768,link.c_str());
    if(!configured[0])throw std::runtime_error("O vinculo da New Experience nao indica a pasta do projeto.");
    fs::path project=configured;
    if(project.is_relative())project=executable_directory/project;
    project=fs::weakly_canonical(project);
    if(!fs::is_regular_file(project/L"config"/L"visualizador.xml")||!fs::is_regular_file(project/L"src"/L"viewer_core.cpp"))
        throw std::runtime_error("Pasta da New Experience ausente ou incompleta: "+utf8(project.wstring()));
    return project;
}
struct Loaded {
    Settings settings;std::vector<std::shared_ptr<const Model>>players;CoachAsset coach;
    std::vector<ClubPlayerRow>roster;
    DressingPrints dressing_prints;
    PressResources press;
    TrainingResources training;
    std::string player_name,error,warning;
};
static unsigned pose_mode(int scene){return scene==0?PoseSeatedCoach:scene==3?PoseIndividual:scene==4?PoseCoachAny:PoseGroup;}
static unsigned default_pose(int scene){return scene==0?205:scene==3?101:scene==4?201:1;}
static Loaded load_assets(Settings s,std::vector<ClubPlayerRow>rows){Loaded out;out.settings=s;try{
    if(!valid_scene(s.scene))throw std::runtime_error("Esta cena foi removida. Escolha Academia ou outro ambiente da biblioteca.");Assets assets(s.game);if(rows.empty())throw std::runtime_error("Este clube não tem jogadores no banco instalado");
    auto selected=std::find_if(rows.begin(),rows.end(),[&](const auto&r){return r.player_id==s.player;});if(selected==rows.end())selected=rows.begin();out.settings.player=selected->player_id;out.player_name=selected->name;
    if(s.scene==0||s.scene==4){out.coach=assets.coach(rows.front());if(!out.coach.model){out.warning="O clube não tem um modelo 3D de técnico disponível. Nenhum outro técnico foi substituído.";if(s.scene==4)throw std::runtime_error(out.warning);}}
    if(s.scene==4){return out;}
    if(s.scene==6||s.scene==7){auto metadata=std::make_shared<Model>();metadata->team_id=s.club;metadata->club_colors_valid=true;for(int k=0;k<3;++k){auto c=rows.front().club_colors[k];metadata->club_colors[k]={float((c>>16)&255)/255,float((c>>8)&255)/255,float(c&255)/255};}Texture crest;if(assets.crest(s.club,crest)){metadata->crest_texture=0;metadata->textures.push_back(std::move(crest));}out.players.push_back(metadata);out.training=load_training_resources(assets,wide(s.game),s.club);return out;}
    if(s.scene==0){for(auto&id:out.settings.press_slots)if(id==-2)id=selected->player_id;std::vector<ClubPlayerRow>chosen={*selected};for(int id:out.settings.press_slots)if(id>0&&std::none_of(chosen.begin(),chosen.end(),[&](auto&r){return r.player_id==id;})){auto at=std::find_if(rows.begin(),rows.end(),[&](auto&r){return r.player_id==id;});if(at!=rows.end())chosen.push_back(*at);}rows=std::move(chosen);out.press=load_press_resources(assets,wide(s.game),s.club,s.press_competition);}
    else if(s.scene==3)rows={*selected};else{size_t limit=s.scene==1?24:11;if(rows.size()>limit)rows.resize(limit);}
    out.roster=rows;
    if(s.scene==1)out.dressing_prints=load_dressing_prints(assets,wide(s.game),s.club);
    for(auto&r:rows){auto model=std::make_shared<Model>(assets.load(r));if(model->parts.empty())throw std::runtime_error("Modelo indisponível: "+std::string(r.name)+". "+model->diagnostic);out.players.push_back(std::move(model));}
    return out;
}catch(const std::exception&e){out.error=e.what();return out;}}
static std::shared_ptr<Model> compose(const Loaded&loaded,const Settings&s,bool edit_coach){
    if(!loaded.error.empty())throw std::runtime_error(loaded.error);pose_edits=s.joints;pose_player=s.player;pose_coach=edit_coach;pose_bones.clear();scene_actors.clear();team_bones.clear();Model result;
    struct TeamGuard {TeamGuard(int scene){team_editing=scene==0||scene==5;team_apply_edits=scene!=5;}~TeamGuard(){team_editing=team_apply_edits=false;team_bones.clear();}}team_guard(s.scene);
    team_edits=s.actors;
    if(s.scene==0&&!s.joints.empty()){int id=edit_coach?-s.club:s.player;if(!actor_edit(team_edits,id)){ActorEdit legacy;legacy.player=id;legacy.joints=s.joints;team_edits.push_back(legacy);}}
    manual_floors.clear();
    if(animation_frame.empty()&&(s.scene==0||s.scene==3||s.scene==4)){
        auto has_move=[](const std::vector<JointEdit>&list){return std::any_of(list.begin(),list.end(),[](const auto&e){return e.translation.x!=0||e.translation.y!=0||e.translation.z!=0;});};
        auto baseline=[&](const std::shared_ptr<const Model>&source,unsigned pose,bool coach){if(!source)return;auto base=*source;auto saved_edits=pose_edits;bool apply=team_apply_edits;pose_edits.clear();team_apply_edits=false;capture_manual_floor=true;if(coach)apply_coach_pose(base,pose);else apply_presentation_pose(base,false,nullptr,pose);capture_manual_floor=false;team_apply_edits=apply;pose_edits=std::move(saved_edits);};
        if(s.scene==3&&has_move(s.joints))baseline(loaded.players.front(),s.pose,false);
        if(s.scene==4&&has_move(s.joints))baseline(loaded.coach.model,s.pose,true);
        if(s.scene==0){auto*a=actor_edit(team_edits,-s.club);if(a&&has_move(a->joints))baseline(loaded.coach.model,s.pose,true);auto*p=actor_edit(team_edits,s.player);if(p&&has_move(p->joints))baseline(loaded.players.front(),s.pose==206?302:301,false);}
    }
    if(s.scene==0)result=build_press_room(loaded.players,loaded.coach,loaded.press,s);
    else if(s.scene==1){pose_edits.clear();result=build_dressing_room(loaded.players,loaded.roster,loaded.dressing_prints);pose_bones.clear();}
    else if(s.scene==3){result=*loaded.players.front();if(!apply_presentation_pose(result,false,nullptr,s.pose))throw std::runtime_error("Esta pose não é compatível com o esqueleto deste jogador");}
    else if(s.scene==4){result=*loaded.coach.model;if(!apply_coach_pose(result,s.pose)){result=*loaded.coach.model;result.diagnostic+="; pose indisponível, geometria original mantida";}}
    else if(s.scene==5){pose_edits.clear();pose_coach=false;team_edits=s.actors;result=assemble_editable_team(loaded.players,s.pose);for(auto&a:scene_actors)if(a.player==s.player)pose_bones=a.bones;}
    else if(s.scene==6||s.scene==7){pose_edits.clear();result=build_training_center(*loaded.players.front(),loaded.training,s.scene==7);}
    else throw std::runtime_error("Cena indisponível");
    if(result.parts.empty())throw std::runtime_error("A cena não pôde ser construída com os modelos disponíveis");
    if(s.scene==0)for(auto&a:scene_actors)if(a.player==(edit_coach?-s.club:s.player))pose_bones=a.bones;
    if(s.scene==1){edit_dressing_objects(result,s.objects);if(s.room_cutaway)open_dressing_room(result);}else if(s.scene==0){edit_dressing_objects(result,s.objects);if(s.room_cutaway)open_press_room(result);}else if(s.scene==6||s.scene==7){edit_dressing_objects(result,s.objects);if(s.room_cutaway)open_training_center(result);}else edit_objects(result,s.objects);return std::make_shared<Model>(std::move(result));
}
static void frame_model(Camera&c,const Model&m,int scene){if(scene==1){dressing_camera_view(c,0);return;}if(scene==0){press_camera_view(c,1);return;}if(scene==6||scene==7){training_camera_view(c,scene,0);return;}auto b=bounds(m);c.orbit=true;c.yaw=0;c.pitch=0;c.fov=45;c.target=b.center;c.distance=std::max(80.f,b.radius*2.7f);if(scene==3||scene==4){c.target={0,90,0};c.distance=285;}c.synchronize_orbit();}
