    const ClubPlayerRow*player_info(int id)const{auto list=catalog.rosters.find(settings.club);if(list==catalog.rosters.end())return nullptr;auto at=std::find_if(list->second.begin(),list->second.end(),[&](const auto&r){return r.player_id==id;});return at==list->second.end()?nullptr:&*at;}
    ActorEdit&selected_actor_edit(){int id=selected_actor_id();auto at=std::find_if(settings.actors.begin(),settings.actors.end(),[&](const auto&a){return a.player==id;});if(at==settings.actors.end()){settings.actors.push_back(ActorEdit{id});if(!settings.joints.empty()&&settings.scene!=5){settings.actors.back().joints=settings.joints;settings.joints.clear();}return settings.actors.back();}return *at;}
