    void log(const std::string&s){std::ofstream out(root/L"visualizador.log",std::ios::app|std::ios::binary);out<<s<<'\n';}
    void load_catalog(){catalog.load(wide(settings.game));strncpy_s(game_path,settings.game.c_str(),_TRUNCATE);if(!catalog.rosters.count(settings.club))settings.club=catalog.clubs.front().id;}
    const Club*club()const{auto it=std::find_if(catalog.clubs.begin(),catalog.clubs.end(),[&](const auto&c){return c.id==settings.club;});return it==catalog.clubs.end()?nullptr:&*it;}
    std::vector<ClubPlayerRow>rows()const{auto it=catalog.rosters.find(settings.club);return it==catalog.rosters.end()?std::vector<ClubPlayerRow>{}:it->second;}
    void begin_load(bool preserve=false){if(loading)return;camera_playing=false;camera_saved=false;films.clear();error.clear();message="Carregando modelos e texturas do FIFA...";loading=true;keep_camera=preserve;auto s=settings;auto r=rows();pending=std::async(std::launch::async,[s,r=std::move(r)]()mutable{return load_assets(s,std::move(r));});}
    void rebuild(){try{prepare_animation();Settings current=settings;if(playing&&!imported_enabled)current.joints=sample_keys(settings.keys,animation_time);animation_frame.clear();imported_sample.clear();if(imported_enabled&&clip.valid()&&(settings.scene==3||settings.scene==4)){imported_sample=clip.sample(animation_time);animation_frame=retarget_frame(imported_sample,settings.mapping,settings.root_motion);}model=compose(loaded,current,edit_coach);bones=pose_bones;actors=scene_actors;if(!renderer.model(model))throw std::runtime_error("Não foi possível enviar a cena para o renderizador");error.clear();}catch(const std::exception&e){playing=false;error=e.what();log(error);}}
    void poll(){if(!loading||pending.wait_for(std::chrono::milliseconds(0))!=std::future_status::ready)return;loaded=pending.get();loading=false;if(!loaded.error.empty()){error=loaded.error;message="";log(error);return;}settings.player=loaded.settings.player;if(settings.scene==0)settings.press_slots=loaded.settings.press_slots;has_loaded=true;bone_index=object_index=0;if(!settings.keys.empty()&&settings.fbx_file.empty())settings.joints=sample_keys(settings.keys,animation_time);rebuild();if(settings.scene==5&&!actors.empty()){if(std::none_of(actors.begin(),actors.end(),[&](const auto&a){return a.player==settings.player;}))settings.player=actors.front().player;auto requested_tab=selected_tab;select_actor(settings.player);selected_tab=requested_tab;}for(size_t i=0;i<bones.size();++i)if(bones[i].name=="RightArm"){bone_index=int(i);break;}if(model&&!keep_camera)frame_model(settings.camera,*model,settings.scene);message=loaded.warning.empty()?"Cena carregada dos arquivos do jogo.":loaded.warning;}
    void scene_select(int s){if(!valid_scene(s)||s==settings.scene)return;camera_playing=false;camera_saved=false;film_id.clear();playing=false;animation_frame.clear();settings.scene=s;settings.room_cutaway=false;settings.pose=default_pose(s);settings.joints.clear();settings.objects.clear();settings.actors.clear();settings.keys.clear();settings.mapping.clear();settings.fbx_file.clear();imported_enabled=false;mapping_pending=true;dirty=false;show_bones=false;edit_coach=s==0||s==4;preset=root/L"presets"/scene_files[s];begin_load();}
    void save_preset(){try{if(loading||!has_loaded)throw std::runtime_error("Espere a cena carregar antes de salvar");if(!path_inside(preset,root))throw std::runtime_error("Salve o XML dentro da pasta deste visualizador, por exemplo em presets");settings.fbx_time=animation_time;save_settings(preset,settings);save_camera_library(root/L"presets"/L"biblioteca-cenas.xml",settings);dirty=false;message="Cena salva. Biblioteca e ajustes preservados no visualizador.";}catch(const std::exception&e){error=e.what();}}
    void resize(UINT w,UINT h){if(!swap||!w||!h)return;context->OMSetRenderTargets(0,nullptr,nullptr);backbuffer.Reset();if(FAILED(swap->ResizeBuffers(0,w,h,DXGI_FORMAT_UNKNOWN,0)))return;ComPtr<ID3D11Texture2D>tex;if(SUCCEEDED(swap->GetBuffer(0,IID_PPV_ARGS(&tex))))device->CreateRenderTargetView(tex.Get(),nullptr,&backbuffer);width=w;height=h;}
    bool create_device(){DXGI_SWAP_CHAIN_DESC d={};d.BufferCount=2;d.BufferDesc.Format=DXGI_FORMAT_R8G8B8A8_UNORM;d.BufferUsage=DXGI_USAGE_RENDER_TARGET_OUTPUT;d.OutputWindow=window;d.SampleDesc.Count=1;d.Windowed=TRUE;d.SwapEffect=DXGI_SWAP_EFFECT_DISCARD;HRESULT hr=D3D11CreateDeviceAndSwapChain(nullptr,D3D_DRIVER_TYPE_HARDWARE,nullptr,0,nullptr,0,D3D11_SDK_VERSION,&d,&swap,&device,nullptr,&context);if(FAILED(hr))hr=D3D11CreateDeviceAndSwapChain(nullptr,D3D_DRIVER_TYPE_WARP,nullptr,0,nullptr,0,D3D11_SDK_VERSION,&d,&swap,&device,nullptr,&context);if(FAILED(hr))return false;renderer.device(device.Get());resize(width,height);return bool(backbuffer);}
    void screenshot(){if(!model)return;SYSTEMTIME t;GetLocalTime(&t);wchar_t filename[120];swprintf_s(filename,L"%04u%02u%02u-%02u%02u%02u-%03u-cena-%d.png",t.wYear,t.wMonth,t.wDay,t.wHour,t.wMinute,t.wSecond,t.wMilliseconds,settings.scene);auto output=root/L"renders"/filename;if(save_png(device.Get(),context.Get(),renderer.image(),output)){message="Imagem salva em renders/"+utf8(filename);log(message);}else error="Não foi possível salvar a imagem";}
