void App::refresh_cinematics(){
    films.clear();if(!model)return;films=cinematic_catalog(settings.scene,*model,loaded.roster,settings.player);
    for(auto&s:settings.camera_scenes)if(s.environment==settings.scene)films.push_back(s);
    if(!film()&&!films.empty())film_id=films.front().id;
}
void App::choose_cinematic(const std::string&id,float time){
    try{camera_playing=false;if(settings.room_cutaway){settings.room_cutaway=false;rebuild();}refresh_cinematics();film_id=id;auto*s=film();if(!s)throw std::runtime_error("Cena não encontrada neste ambiente");
        if(!camera_saved){camera_before=settings.camera;camera_saved=true;}camera_time=std::clamp(time,0.f,camera_scene_duration(*s));settings.camera=sample_camera_scene(*s,camera_time);shot_index=0;strncpy_s(film_name,s->name.c_str(),_TRUNCATE);error.clear();message="Cena cinematográfica pronta. Reproduza ou percorra a linha do tempo.";
    }catch(const std::exception&e){error=e.what();camera_playing=false;}
}
void App::stop_cinematic(){camera_playing=false;camera_time=0;if(camera_saved)settings.camera=camera_before;camera_saved=false;message="Câmera livre restaurada.";}
void App::toggle_cinematic(){if(camera_playing){camera_playing=false;return;}auto id=film_id;float time=camera_time;choose_cinematic(id,time);if(error.empty()){if(auto*s=film()){if(camera_time>=camera_scene_duration(*s))camera_time=0;settings.camera=sample_camera_scene(*s,camera_time);camera_playing=true;}}}
void App::tick_cinematic(float dt){
    if(!camera_playing||loading)return;try{auto*s=film();if(!s){camera_playing=false;return;}float end=camera_scene_duration(*s);camera_time+=std::min(dt,.1f)*camera_speed;
        if(camera_time>=end){if(camera_loop)camera_time=fmodf(camera_time,end);else{camera_time=end;camera_playing=false;}}settings.camera=sample_camera_scene(*s,camera_time);
    }catch(const std::exception&e){camera_playing=false;error=e.what();}
}
void App::draw_library(){
    auto flags=[&](const char*name){if(library_tab==name){library_tab.clear();return ImGuiTabItemFlags_SetSelected;}return ImGuiTabItemFlags_None;};
    if(ImGui::BeginTabBar("library-pages")){
        if(ImGui::BeginTabItem("Ambientes",nullptr,flags("environments"))){
            const char*names[]={"Vestiário","Sala de imprensa","Academia","CT de treinamento","Estúdio de modelos"};int scenes[]={1,0,6,7,3};for(int i=0;i<5;++i)if(ImGui::Selectable(names[i],i==4?(settings.scene>=3&&settings.scene<=5):settings.scene==scenes[i],0,ImVec2(0,30))){scene_select(scenes[i]);library_tab="scenes";selected_tab="cinematics";}
            ImGui::TextWrapped("Escolha um ambiente para ver suas cenas. Modelos, poses e movimentos ficam separados.");ImGui::EndTabItem();}
        if(ImGui::BeginTabItem("Cenas",nullptr,flags("scenes"))){
            ImGui::TextDisabled("%s",scene_names[settings.scene]);ImGui::BeginChild("film-library",ImVec2(0,184),true);
            if(settings.scene==0){ImGui::TextUnformatted("Coletiva à mesa");ImGui::Separator();}
            if(settings.scene>=3&&settings.scene<=5){for(int i=3;i<6;++i)if(ImGui::Selectable(scene_names[i],settings.scene==i))scene_select(i);}
            std::string chosen;for(auto&s:films){std::string label=s.name+"##film-"+s.id;if(ImGui::Selectable(label.c_str(),s.id==film_id,0,ImVec2(0,24)))chosen=s.id;}if(!chosen.empty()){choose_cinematic(chosen);selected_tab="cinematics";}
            if(films.empty())ImGui::TextWrapped(loading?"Carregando cenas...":"Crie enquadramentos na aba Cenas.");ImGui::EndChild();
            ImGui::TextDisabled("%zu cenas cinematográficas",films.size());ImGui::EndTabItem();}
        if(ImGui::BeginTabItem("Animações",nullptr,flags("animations"))){
            ImGui::TextWrapped("Movimentos de pessoas: poses-chave e FBX. Não alteram a geometria do ambiente.");
            if(ImGui::Button("Jogador: poses e animações",ImVec2(-1,28))){scene_select(3);selected_tab="animation";}if(ImGui::Button("Técnico: poses e animações",ImVec2(-1,28))){scene_select(4);selected_tab="animation";}
            if(ImGui::Button("Foto da equipe e poses",ImVec2(-1,28))){scene_select(5);selected_tab="pose";}if(ImGui::Button("Bancos originais do FIFA",ImVec2(-1,28)))selected_tab="fifa";ImGui::EndTabItem();}
        ImGui::EndTabBar();}
}
