    if(s&&ImGui::Button("Duplicar cena selecionada",ImVec2(-1,27))){auto original=*film();if(settings.camera_scenes.size()>=100){error="Limite de 100 cenas personalizadas.";return;}original.id="custom-"+std::to_string(GetTickCount64());while(std::any_of(settings.camera_scenes.begin(),settings.camera_scenes.end(),[&](auto&old){return old.id==original.id;}))original.id+='x';original.name+=" (cópia)";film_id=original.id;settings.camera_scenes.push_back(std::move(original));strncpy_s(film_name,settings.camera_scenes.back().name.c_str(),_TRUNCATE);dirty=true;refresh_cinematics();}
    auto at=std::find_if(settings.camera_scenes.begin(),settings.camera_scenes.end(),[&](auto&scene){return scene.id==film_id;});if(at==settings.camera_scenes.end()){ImGui::TextDisabled("Duplique uma cena pronta para editá-la.");return;}auto&scene=*at;
    if(ImGui::InputText("Nome##filme",film_name,sizeof(film_name))){if(strlen(film_name)>0&&strlen(film_name)<=160){scene.name=film_name;dirty=true;refresh_cinematics();}}
    shot_index=std::clamp(shot_index,0,int(scene.keys.size())-1);if(ImGui::BeginCombo("Enquadramento",("Ponto "+std::to_string(shot_index+1)).c_str())){for(size_t i=0;i<scene.keys.size();++i){auto label="Ponto "+std::to_string(i+1)+" — "+std::to_string(int(scene.keys[i].time))+" s";if(ImGui::Selectable(label.c_str(),int(i)==shot_index))shot_index=int(i);}ImGui::EndCombo();}
    auto&key=scene.keys[shot_index];bool changed=false;ImGui::BeginDisabled(shot_index==0);float lo=shot_index?scene.keys[shot_index-1].time+.1f:0,hi=size_t(shot_index+1)<scene.keys.size()?scene.keys[shot_index+1].time-.1f:600;changed|=ImGui::DragFloat("Tempo (s)",&key.time,.1f,lo,hi,"%.1f",ImGuiSliderFlags_AlwaysClamp);ImGui::EndDisabled();
    const char*transitions[]={"Movimento suave","Movimento linear","Corte com fade"};changed|=ImGui::Combo("Transição",&key.transition,transitions,3);
    if(ImGui::Button("Gravar câmera neste ponto",ImVec2(-1,27))){int transition=key.transition;key=capture_camera_key(settings.camera,key.time);key.transition=transition;changed=true;}
    if(ImGui::Button("Ir para este ponto",ImVec2(-1,27)))choose_cinematic(film_id,key.time);
    ImGui::BeginDisabled(scene.keys.size()>=256||scene.keys.back().time>595);if(ImGui::Button("Adicionar ponto ao final",ImVec2(-1,27))){scene.keys.push_back(capture_camera_key(settings.camera,scene.keys.back().time+5));shot_index=int(scene.keys.size())-1;changed=true;}ImGui::EndDisabled();
    ImGui::BeginDisabled(scene.keys.size()<=2||shot_index==0);if(ImGui::Button("Remover este ponto",ImVec2(-1,27))){scene.keys.erase(scene.keys.begin()+shot_index);shot_index=std::min(shot_index,int(scene.keys.size())-1);changed=true;}ImGui::EndDisabled();
    if(changed){dirty=true;refresh_cinematics();}ImGui::TextWrapped("Salvar cena guarda os enquadramentos junto com o ambiente no XML. As cenas prontas ficam preservadas.");
