static float axis(SHORT n){float x=float(n)/32767;return fabsf(x)<.18f?0:(x-copysignf(.18f,x))/.82f;}
static bool main_bone(const std::string&name){static const std::set<std::string>body={"Reference","Root","Hips","Spine","Spine1","Spine2","Spine3","Neck","Neck1","Head","LeftShoulder","RightShoulder","LeftArm","RightArm","LeftForeArm","RightForeArm","LeftHand","RightHand","LeftUpLeg","RightUpLeg","LeftLeg","RightLeg","LeftFoot","RightFoot","LeftToeBase","RightToeBase"};return body.count(name)||name.rfind("LeftHand",0)==0||name.rfind("RightHand",0)==0;}
static bool project(const Camera&c,Vec3 p,ImVec2 start,ImVec2 size,ImVec2&screen){auto f=c.forward();auto eye=XMVectorSet(c.position.x,c.position.y,c.position.z,1);auto view=XMMatrixLookAtRH(eye,eye+XMVectorSet(f.x,f.y,f.z,0),XMVectorSet(0,1,0,0));auto proj=XMMatrixPerspectiveFovRH(XMConvertToRadians(c.fov),size.x/size.y,.1f,100000);auto a=XMVector3TransformCoord(XMVectorSet(p.x,p.y,p.z,1),view*proj);float z=XMVectorGetZ(a);if(z<0||z>1)return false;screen={start.x+(XMVectorGetX(a)+1)*size.x*.5f,start.y+(1-XMVectorGetY(a))*size.y*.5f};return screen.x>=start.x&&screen.x<=start.x+size.x&&screen.y>=start.y&&screen.y<=start.y+size.y;}
bool App::draw_gizmo(ImVec2 start,ImVec2 size){
    bool previous=gizmo_was_using;gizmo_was_using=false;
    if(!show_bones||bones.empty()||loading)return previous;
    bone_index=std::clamp(bone_index,0,int(bones.size())-1);BonePoint bone=bones[bone_index];
    auto&cam=settings.camera;auto f=cam.forward();auto eye=XMVectorSet(cam.position.x,cam.position.y,cam.position.z,1);
    XMFLOAT4X4 view,projection;XMStoreFloat4x4(&view,XMMatrixLookAtRH(eye,eye+XMVectorSet(f.x,f.y,f.z,0),XMVectorSet(0,1,0,0)));XMStoreFloat4x4(&projection,XMMatrixPerspectiveFovRH(XMConvertToRadians(cam.fov),size.x/size.y,.1f,100000));
    ImGuizmo::SetDrawlist(ImGui::GetWindowDrawList());ImGuizmo::SetRect(start.x,start.y,size.x,size.y);ImGuizmo::SetOrthographic(false);ImGuizmo::SetGizmoSizeClipSpace(.10f);
    auto matrix=bone.frame;bool changed=ImGuizmo::Manipulate(&view._11,&projection._11,gizmo_rotate?ImGuizmo::ROTATE:ImGuizmo::TRANSLATE,gizmo_local?ImGuizmo::LOCAL:ImGuizmo::WORLD,&matrix._11);
    gizmo_was_using=ImGuizmo::IsUsing();bool block=previous||gizmo_was_using||ImGuizmo::IsOver();
    if(changed){auto&joints=selected_joints();auto at=std::find_if(joints.begin(),joints.end(),[&](const auto&j){return j.name==bone.name;});auto old=at==joints.end()?JointEdit{bone.name}:*at;auto next=edit_from_gizmo(bone,old,matrix,!gizmo_rotate);
        next.translation.x=std::clamp(next.translation.x,-100.f,100.f);next.translation.y=std::clamp(next.translation.y,-100.f,100.f);next.translation.z=std::clamp(next.translation.z,-100.f,100.f);
        if(at==joints.end())joints.push_back(next);else *at=next;playing=false;dirty=true;rebuild();
    }return block;
}
