static void write_webcam_fifa_model(const Model&m,const ClubPlayerRow&player,const fs::path&target){
    if(m.parts.empty()||!m.skeleton||m.skeleton->names.empty()||m.skeleton->names.size()!=m.skeleton->parents.size()||m.skeleton->names.size()!=m.skeleton->inverse_bind.size())throw std::runtime_error("Modelo FIFA sem malha ou esqueleto válido");
    auto temporary=target;temporary+=L".tmp";fs::create_directories(target.parent_path());std::ofstream out(temporary,std::ios::binary|std::ios::trunc);if(!out)throw std::runtime_error("Não foi possível criar o arquivo do jogador FIFA");
    auto u32=[&](uint32_t v){out.write(reinterpret_cast<const char*>(&v),4);};auto f32=[&](float v){out.write(reinterpret_cast<const char*>(&v),4);};auto str=[&](const std::string&s){if(s.size()>4096)throw std::runtime_error("Nome de peça do jogador excede o limite");u32(uint32_t(s.size()));out.write(s.data(),std::streamsize(s.size()));};
    out.write("FF3D0003",8);u32(uint32_t(m.parts.size()));u32(uint32_t(m.textures.size()));u32(uint32_t(m.skeleton->names.size()));u32(uint32_t(player.player_id));u32(uint32_t(m.height_cm));str(utf8(wide(player.name)));
    /* Geometry is already height-scaled and grounded by Assets::load(). Apply
       the same transform to inverse-bind matrices so browser skinning keeps
       the original FIFA bind pose. DirectX matrices use row vectors. */
    float scale=m.bind_scale>0?m.bind_scale:1.f;auto inverse_geometry=XMMatrixScaling(1.f/scale,1.f/scale,1.f/scale)*XMMatrixTranslation(0,m.bind_feet,0);
    for(size_t i=0;i<m.skeleton->names.size();++i){str(m.skeleton->names[i]);u32(m.skeleton->parents[i]==0xffff?UINT32_MAX:uint32_t(m.skeleton->parents[i]));XMFLOAT4X4 raw,adjusted;memcpy(&raw,m.skeleton->inverse_bind[i].data(),64);XMStoreFloat4x4(&adjusted,inverse_geometry*XMLoadFloat4x4(&raw));auto*p=&adjusted._11;for(int k=0;k<16;++k)f32(p[k]);}
    for(const auto&p:m.parts){str(p.name);str(p.asset);u32(uint32_t(p.texture));u32(p.skinned?1:0);u32(p.blend?1:0);f32(p.alpha_scale);u32(uint32_t(p.hair_coeff_texture));for(float v:{p.color.x,p.color.y,p.color.z,p.tint.x,p.tint.y,p.tint.z})f32(v);u32(uint32_t(p.vertices.size()));u32(uint32_t(p.indices.size()));
        for(const auto&v:p.vertices){for(float x:{v.position.x,v.position.y,v.position.z,v.normal.x,v.normal.y,v.normal.z,v.u,v.v})f32(x);out.write(reinterpret_cast<const char*>(v.joints),sizeof(v.joints));out.write(reinterpret_cast<const char*>(v.weights),sizeof(v.weights));if(p.skinned)for(int j=0;j<8;++j)if(v.weights[j]&&v.joints[j]>=m.skeleton->names.size())throw std::runtime_error("O modelo FIFA contém um peso fora do esqueleto");}
        if(!p.indices.empty())out.write(reinterpret_cast<const char*>(p.indices.data()),std::streamsize(p.indices.size()*4));}
    for(const auto&t:m.textures){u32(t.width);u32(t.height);u32(t.format);u32(uint32_t(t.bytes.size()));if(!t.bytes.empty())out.write(reinterpret_cast<const char*>(t.bytes.data()),std::streamsize(t.bytes.size()));}
    if(!out)throw std::runtime_error("Falha ao gravar a malha do jogador FIFA");out.close();if(!out)throw std::runtime_error("Falha ao concluir a malha do jogador FIFA");if(!MoveFileExW(temporary.c_str(),target.c_str(),MOVEFILE_REPLACE_EXISTING|MOVEFILE_WRITE_THROUGH))throw std::runtime_error("Não foi possível publicar a malha do jogador FIFA");
}
static int export_flamengo_goalkeeper(const Settings&settings,const Catalog&catalog,const fs::path&target,const fs::path&log_path,int requested_player=0){
    const Club*club=nullptr;for(const auto&candidate:catalog.clubs)if(candidate.name.find("Flamengo")!=std::string::npos){club=&candidate;if(candidate.id==settings.club)break;}
    if(!club)throw std::runtime_error("Flamengo não foi encontrado no banco desta instalação do FIFA 16");auto roster=catalog.rosters.find(club->id);if(roster==catalog.rosters.end())throw std::runtime_error("O elenco do Flamengo está vazio no banco desta instalação");
    auto goalkeeper=std::find_if(roster->second.begin(),roster->second.end(),[](const auto&r){return std::string(r.name).find("Rossi")!=std::string::npos&&r.position==0;});
    if(goalkeeper==roster->second.end())goalkeeper=std::find_if(roster->second.begin(),roster->second.end(),[](const auto&r){return std::string(r.name).find("Rossi")!=std::string::npos;});
    if(goalkeeper==roster->second.end())goalkeeper=std::find_if(roster->second.begin(),roster->second.end(),[](const auto&r){return r.position==0;});
        if(requested_player>0)goalkeeper=std::find_if(roster->second.begin(),roster->second.end(),[&](const auto&r){return r.player_id==requested_player;});
    if(goalkeeper==roster->second.end())throw std::runtime_error("Jogador não encontrado no elenco do Flamengo desta instalação");
    fs::create_directories(target.parent_path());
    auto quote=[](const std::string&s){std::string result="\"";for(unsigned char c:s){if(c=='\"'||c=='\\')result+='\\';if(c>=32)result+=char(c);}return result+"\"";};
    std::ofstream index(target.parent_path()/L"flamengo-players.json",std::ios::binary|std::ios::trunc);index<<"{\"team\":\"Flamengo\",\"players\":[";bool first=true;
    for(const auto&r:roster->second){if(!first)index<<',';first=false;index<<"{\"id\":"<<r.player_id<<",\"name\":"<<quote(r.name)<<",\"position\":"<<r.position<<'}';}index<<"]}";
    Assets assets(settings.game);auto model=assets.load(*goalkeeper);if(model.parts.empty())throw std::runtime_error("O FIFA não conseguiu montar o jogador: "+std::string(goalkeeper->name)+". "+model.diagnostic);write_webcam_fifa_model(model,*goalkeeper,target);
    std::ofstream log(log_path,std::ios::app|std::ios::binary);log<<"Webcam FIFA: exportado "<<club->name<<" / "<<goalkeeper->name<<" (#"<<goalkeeper->player_id<<") para "<<utf8(target.wstring())<<"\n";return 0;
}
